/* ML-DSA known-answer vectors.

   FIPS 204: the NIST ACVP server's test vectors,
   https://github.com/usnistgov/ACVP-Server, commit
   975de31eb83d87039ec88934fdc47d8c312b892d, files
   gen-val/json-files/ML-DSA-keyGen-FIPS204/internalProjection.json,
   gen-val/json-files/ML-DSA-sigGen-FIPS204/internalProjection.json and
   gen-val/json-files/ML-DSA-sigVer-FIPS204/internalProjection.json.  Each
   group names the test group (tgId) and test case (tcId) it was copied
   from; the shortest message of its kind was taken.  "External" is the
   interface of FIPS 204 algorithm 2 (the message and a context string),
   "internal" algorithm 7 (the message is M' as formed by the caller).  The
   deterministic cases sign with rnd of 32 zero bytes.

   RFC 9881 (ML-DSA in X.509): the private keys of appendix C.1 in the seed,
   expandedKey and both forms for the three parameter sets, a certificate
   for each set from C.3, and the inconsistent keys of C.4.

   A hex value is a NULL-terminated list of string pieces, because a single
   literal may not exceed what ISO C99 requires compilers to support; a PEM
   text is such a list of pieces of whole lines.  Use either as the
   initialiser of a const char *const array.  */

